use super::*;

fn rules(text: &str) -> Vec<Rule> {
    lint_text("description", text)
        .into_iter()
        .map(|v| v.rule)
        .collect()
}

fn commit(email: &str, message: &str) -> Commit {
    Commit {
        sha: "0123456789abcdef".into(),
        author_name: "A".into(),
        author_email: email.into(),
        message: message.into(),
    }
}

#[test]
fn tool_footers_are_flagged() {
    for text in [
        "Fixes it.\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)",
        "Generated with Claude Code",
        "This PR was generated by ChatGPT.",
        "Created with Cursor",
        "_Written by Codex_",
    ] {
        assert_eq!(rules(text), [Rule::ToolFooter], "{text}");
    }
}

#[test]
fn generated_prose_is_not_a_footer() {
    for text in [
        "The nine classes are generated by scripts/gen-typed-arrays.py.",
        "Programs generated with seed 1: 163 identical.",
        "The code generated for JSON.stringify calls the runtime once.",
        "Generated with `claude` as the program name.",
    ] {
        assert!(rules(text).is_empty(), "{text}");
    }
}

#[test]
fn trailers_are_flagged() {
    for text in [
        "Co-Authored-By: Claude <noreply@anthropic.com>",
        "co-authored-by: Someone <a@b.c>",
        "  Generated-by: some tool",
        "> Assisted-by: an agent",
        "Claude-Session: abc",
    ] {
        assert_eq!(rules(text), [Rule::Trailer], "{text}");
    }
    // Quoted as code it is about trailers, not one.
    assert!(rules("No `Co-authored-by:` trailers.").is_empty());
    assert!(rules("```\nCo-authored-by: X <x@y>\n```").is_empty());
    assert!(rules("Mentions co-authored-by: in the middle of a line.").is_empty());
}

#[test]
fn chat_and_session_links_are_flagged() {
    for text in [
        "Session: https://claude.ai/code/session_01ABC",
        "see https://chatgpt.com/share/abc-def",
        "<https://chat.openai.com/c/123>",
        "https://gemini.google.com/app/1",
        "[log](https://claude.ai/chat/xyz)",
    ] {
        assert_eq!(rules(text), [Rule::ChatLink], "{text}");
    }
}

#[test]
fn ordinary_links_pass() {
    for text in [
        "Closes #12. See https://github.com/velt-lang/velt/pull/1068 and #1069.",
        "https://github.com/github/gh-stack",
        "Node's docs: https://nodejs.org/api/fs.html",
        "https://notclaude.ai/x and https://my-chatgpt.com/y",
        "The link `https://claude.ai/code` is rejected by the lint.",
    ] {
        assert!(rules(text).is_empty(), "{text}");
    }
}

#[test]
fn machine_paths_are_flagged_even_in_code() {
    for (text, path) in [
        ("built in /Users/alice/dev/velt", "/Users/alice/dev/velt"),
        (
            "`/home/bob/velt/target/debug/velt`",
            "/home/bob/velt/target/debug/velt",
        ),
        (
            r"at C:\Users\carol\velt\x.vlt:3",
            r"C:\Users\carol\velt\x.vlt:3",
        ),
        ("c:/users/dave/x", "c:/users/dave/x"),
        (
            "```\nwrote /private/tmp/x/out.o\n```",
            "/private/tmp/x/out.o",
        ),
        ("/var/folders/ab/T/x", "/var/folders/ab/T/x"),
    ] {
        let v = lint_text("description", text);
        assert_eq!(v.len(), 1, "{text}: {v:?}");
        assert_eq!(v[0].rule, Rule::MachinePath);
        assert_eq!(v[0].text, path);
    }
}

#[test]
fn relative_and_placeholder_paths_pass() {
    for text in [
        "crates/xtask/src/pr_lint.rs and ./scripts/check.sh",
        "Config lives in ~/.velt/config and $HOME/.cache",
        "On macOS: /Users/<name>/Library/Caches",
        "CI: /home/runner/work/velt/velt and /Users/runner/work",
        "the api route /api/Users/1/ and docs/home/x/",
        "/tmp/out.o and /usr/local/bin",
        "temporary files under /private/tmp/ or `/var/folders/`",
        "the /home/ directory and /Users/",
        r"C:\Users\ and C:\Users\<name>\AppData",
    ] {
        assert!(rules(text).is_empty(), "{text}");
    }
}

#[test]
fn review_wording_is_flagged() {
    for text in [
        "Review round 2: fixed the leak.",
        "Addressed the review in 3c5bc8b0.",
        "Changed per review.",
        "Stacked on #1030.",
        "**Stacked on top of #1118**",
        "Two independent reviews of the branch; their findings are fixed.",
        "after the review fixes",
        "An adversarial review found a hole.",
    ] {
        assert_eq!(rules(text), [Rule::ReviewWording], "{text}");
    }
}

#[test]
fn prose_about_reviews_passes() {
    for text in [
        "Contract changes need a maintainer's review.",
        "Open question for review: the compile cost.",
        "Follow-ups from the review: #1174.",
        "The upper reviewer column.",
        "A stack of pull requests (gh stack).",
        "Built on #1097 (merged).",
        "Part of #1135. Closes #12.",
    ] {
        assert!(rules(text).is_empty(), "{text}");
    }
}

#[test]
fn line_numbers_and_title_are_reported() {
    let v = lint_text("title", "ok\nper review");
    assert_eq!(v.len(), 1);
    assert_eq!((v[0].place.as_str(), v[0].line), ("title", 2));
    let text = report(&v);
    assert!(text.contains("title, line 2: review-process wording: per review"));
    assert!(text.contains("fix: "));
}

#[test]
fn commit_authors_must_match_one_expected_email() {
    let authors = vec!["1+me@users.noreply.github.com".to_string()];
    let ok = commit("1+Me@users.noreply.github.com", "sema: a change");
    assert!(lint_commits(&[ok], &authors).is_empty());
    let bad = commit("claude@anthropic.com", "sema: a change");
    let v = lint_commits(&[bad], &authors);
    assert_eq!(v.len(), 1);
    assert_eq!(v[0].rule, Rule::Author);
    assert!(v[0]
        .place
        .starts_with("commit 01234567 (\"sema: a change\")"));
    assert!(v[0].text.contains("expected 1+me@users.noreply.github.com"));
}

#[test]
fn commit_messages_are_checked_too() {
    let authors = vec!["a@b".to_string()];
    let c = commit(
        "a@b",
        "fix\n\nCo-authored-by: Claude <noreply@anthropic.com>",
    );
    let v = lint_commits(&[c], &authors);
    assert_eq!(
        v.iter().map(|v| v.rule).collect::<Vec<_>>(),
        [Rule::Trailer]
    );
    assert_eq!(v[0].line, 3);
}

#[test]
fn git_log_records_are_parsed() {
    let text = "aaa\x1fA\x1fa@b\x1fsubject\n\nbody\n\x1e\nbbb\x1fB\x1fb@c\x1fone\n\x1e\n";
    let commits = parse_log(text);
    assert_eq!(commits.len(), 2);
    assert_eq!(commits[0].sha, "aaa");
    assert_eq!(commits[0].message, "subject\n\nbody");
    assert_eq!(commits[1].author_email, "b@c");
    assert_eq!(commits[1].message, "one");
}

#[test]
fn the_commits_of_a_branch_are_read_from_git() {
    let dir = std::env::temp_dir().join(format!("xtask-pr-lint-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let git = |args: &[&str], email: &str| {
        let ok = Command::new("git")
            .args(["-c", "user.name=t", "-c"])
            .arg(format!("user.email={email}"))
            .args(["-c", "commit.gpgsign=false"])
            .args(args)
            .current_dir(&dir)
            .output()
            .unwrap();
        assert!(
            ok.status.success(),
            "{}",
            String::from_utf8_lossy(&ok.stderr)
        );
    };
    git(&["init", "-q"], "t@t");
    git(&["commit", "-q", "--allow-empty", "-m", "base"], "t@t");
    git(&["tag", "base"], "t@t");
    git(&["commit", "-q", "--allow-empty", "-m", "one"], "t@t");
    git(
        &["commit", "-q", "--allow-empty", "-m", "two\n\nper review"],
        "x@y",
    );
    let commits = log(&dir, "base..HEAD").unwrap();
    assert_eq!(
        commits
            .iter()
            .map(|c| c.message.as_str())
            .collect::<Vec<_>>(),
        ["one", "two\n\nper review"]
    );
    let v = lint_commits(&commits, &["t@t".to_string()]);
    assert_eq!(
        v.iter().map(|v| v.rule).collect::<Vec<_>>(),
        [Rule::Author, Rule::ReviewWording]
    );
    let _ = std::fs::remove_dir_all(&dir);
}
